package Buffer

import (
	"encoding/binary"
	"math"
)

// ── Camera block ─────────────────────────────────────────────
const (
	BufCameraColPX       = 0  // f32
	BufCameraColPY       = 4  // f32
	BufCameraColPZ       = 8  // f32
	BufCameraColR        = 12 // f32
	BufCameraColPosPhi   = 16 // f32
	BufCameraColPosTheta = 20 // f32
	BufCameraColUpPhi    = 24 // f32
	BufCameraColUpTheta  = 28 // f32
	BufCameraStride      = 32
)

// SetCameraRow writes the Camera row into buf (always 1 row; no row param).
func SetCameraRow(buf []byte, pX float32, pY float32, pZ float32, r float32, posPhi float32, posTheta float32, upPhi float32, upTheta float32) {
	binary.LittleEndian.PutUint32(buf[0:], math.Float32bits(pX))
	binary.LittleEndian.PutUint32(buf[4:], math.Float32bits(pY))
	binary.LittleEndian.PutUint32(buf[8:], math.Float32bits(pZ))
	binary.LittleEndian.PutUint32(buf[12:], math.Float32bits(r))
	binary.LittleEndian.PutUint32(buf[16:], math.Float32bits(posPhi))
	binary.LittleEndian.PutUint32(buf[20:], math.Float32bits(posTheta))
	binary.LittleEndian.PutUint32(buf[24:], math.Float32bits(upPhi))
	binary.LittleEndian.PutUint32(buf[28:], math.Float32bits(upTheta))
}
